const tabId = 118779795;
const allPressReleases = [];

for (let page = 0; page <= 5; page++) {
  const url = `https://www.justice.gov/archives/press-releases-archive?f%5B0%5D=facet_components%3A376&f%5B1%5D=facet_dates%3A2022&page=${page}`;
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });

  const pageItems = await browserjs(tabId, () => {
    // In Drupal views, each result is typically in .views-row or article
    const rows = Array.from(document.querySelectorAll('.views-row'));
    return rows.map(row => {
      const linkEl = row.querySelector('h2 a, h3 a, .views-field-title a, a');
      const dateEl = row.querySelector('time, .date-display-single, .views-field-created');
      return {
        title: linkEl?.textContent?.trim(),
        date: dateEl?.textContent?.trim(),
        url: linkEl?.href
      };
    }).filter(r => r.title && r.url && !r.url.includes('facebook') && !r.url.includes('twitter'));
  });

  console.log(`Page ${page}: found ${pageItems.length} items`);
  allPressReleases.push(...pageItems);
}

// Deduplicate if needed
const unique = [];
const seen = new Set();
for (const item of allPressReleases) {
  if (!seen.has(item.url)) {
    seen.add(item.url);
    unique.push(item);
  }
}

console.log(`Total extracted: ${allPressReleases.length}, Unique: ${unique.length}`);
await write("tmp://atr_2022_press_releases.json", JSON.stringify(unique, null, 2));

